class Solution {
public:
    unordered_map<TreeNode*, TreeNode*> parent;
    vector<int> ans;
    unordered_set<TreeNode*> visited;

    void buildParent(TreeNode* node, TreeNode* par) {
        if (!node) return;
        parent[node] = par;
        buildParent(node->left, node);
        buildParent(node->right, node);
    }

    void findK(TreeNode* node, int dist, int k) {
        if (!node) return;
        if (dist == k) {
            ans.push_back(node->val);
            return;
        }
        for (TreeNode* nxt : {node->left, node->right, parent[node]}) {
            if (nxt && !visited.count(nxt)) {
                visited.insert(nxt);
                findK(nxt, dist + 1, k);
            }
        }
    }

    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        buildParent(root, nullptr);
        visited.insert(target);
        findK(target, 0, k);
        return ans;
    }
};

class Solution {
    Map<TreeNode, TreeNode> parent = new HashMap<>();
    List<Integer> ans = new ArrayList<>();
    Set<TreeNode> visited = new HashSet<>();

    void buildParent(TreeNode node, TreeNode par) {
        if (node == null) return;
        parent.put(node, par);
        buildParent(node.left, node);
        buildParent(node.right, node);
    }

    void findK(TreeNode node, int dist, int k) {
        if (node == null) return;
        if (dist == k) {
            ans.add(node.val);
            return;
        }
        TreeNode[] neighbors = new TreeNode[]{node.left, node.right, parent.get(node)};
        for (TreeNode nxt : neighbors) {
            if (nxt != null && !visited.contains(nxt)) {
                visited.add(nxt);
                findK(nxt, dist + 1, k);
            }
        }
    }

    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        buildParent(root, null);
        visited.add(target);
        findK(target, 0, k);
        return ans;
    }
}

var distanceK = function(root, target, k) {
    const parent = new Map();
    function buildParent(node, par = null) {
        if (!node) return;
        parent.set(node, par);
        buildParent(node.left, node);
        buildParent(node.right, node);
    }
    buildParent(root);

    const ans = [];
    const visited = new Set([target]);

    function findK(node, dist) {
        if (!node) return;
        if (dist === k) {
            ans.push(node.val);
            return;
        }
        for (const nxt of [node.left, node.right, parent.get(node)]) {
            if (nxt && !visited.has(nxt)) {
                visited.add(nxt);
                findK(nxt, dist + 1);
            }
        }
    }

    findK(target, 0);
    return ans;
};
